 "area.territorio": {"it": "Territorio", "en": "The territory"},
 "territorio.h1": {"it": "Territorio", "en": "The territory"},
 "territorio.lead": {"it": "Un borgo in collina, un fiume in pianura e tutto quello che c’è in mezzo.", "en": "A village on the hill, a river on the plain and everything in between."},
 "territorio.sm.0": {"it": "Cos’è il Moon Festival", "en": "What Moon Festival is"},
 "territorio.sm.1": {"it": "Note di regia · 2026", "en": "Director’s notes · 2026"},
 "territorio.sm.2": {"it": "Chi siamo", "en": "Who we are"},
 "territorio.sm.3": {"it": "Territorio", "en": "The territory"},
 "territorio.sm.4": {"it": "Partner", "en": "Partners"},
 "territorio.s0.o": {"it": "Il borgo", "en": "The village"},
 "territorio.s0.h": {"it": "San Raffaele Alto.", "en": "San Raffaele Alto."},
 "territorio.s0.p0": {"it": "San Raffaele Alto è il borgo in collina di San Raffaele Cimena, affacciato sulla pianura chivassese. [DUE RIGHE SUL BORGO: STORIA E VITA DURANTE L’ANNO]", "en": "San Raffaele Alto is the hilltop village of San Raffaele Cimena, overlooking the Chivasso plain. [TWO LINES ON THE VILLAGE: HISTORY AND LIFE DURING THE YEAR]"},
 "territorio.s0.p1": {"it": "Una volta all’anno le strade diventano percorsi, i cortili diventano scene, i balconi osservano, i muri ricevono luce, ombre e suoni.", "en": "Once a year its streets become pathways, courtyards become stages, balconies watch, walls receive light, shadows and sounds."},
 "alt.Ilum-collettivo_MoonFestival_5ed_circo-piazza": {"it": "Spettacolo di circo con un tripode al centro della piazza piena di pubblico.", "en": "A circus show with a tripod rig in the middle of a crowded square."},
 "credito.Ilum-collettivo_MoonFestival_5ed_circo-piazza": {"it": "© Ilum collettivo · Moon Festival, 5ª edizione", "en": "© Ilum collettivo · Moon Festival, 5th edition"},
 "territorio.s1.o": {"it": "Il paesaggio", "en": "The landscape"},
 "territorio.s1.h": {"it": "Tra la Collina Torinese e il Po.", "en": "Between the Turin Hills and the Po."},
 "territorio.s1.p0": {"it": "Le Moon Walk attraversano la pianura chivassese, i sentieri della Collina Torinese e il paesaggio del Parco del Po piemontese, nel territorio della Riserva della Biosfera Collina Po MAB UNESCO.", "en": "The Moon Walks cross the Chivasso plain, the paths of the Turin Hills and the landscape of the Po river park, within the Collina Po UNESCO MAB Biosphere Reserve."},
 "alt.Ilum-collettivo_MoonFestival_5ed_sentiero": {"it": "Due persone camminano su un sentiero di collina sotto il cielo azzurro.", "en": "Two people walk along a hill path under a blue sky."},
 "credito.Ilum-collettivo_MoonFestival_5ed_sentiero": {"it": "© Ilum collettivo · Moon Festival, 5ª edizione", "en": "© Ilum collettivo · Moon Festival, 5th edition"},
 "territorio.s2.o": {"it": "Arrivare", "en": "Getting here"},
 "territorio.s2.h": {"it": "Un borgo di salite e di scale.", "en": "A village of slopes and steps."},
 "territorio.s2.p0": {"it": "San Raffaele Alto presenta pendenze, scalini e pavimentazioni irregolari. Per arrivare e muoversi al festival trovi tutte le indicazioni in Info utili e Accessibilità.", "en": "San Raffaele Alto has slopes, steps and uneven paving. For getting here and moving around the festival, see Practical info and Accessibility."},
 "titolo.territorio": {"it": "Territorio · Moon Festival", "en": "The territory · Moon Festival"},
