 "partner.h1": {"it": "Partner", "en": "Partners"},
 "partner.lead": {"it": "Un piccolo paese. Una grande rete.", "en": "A small village. A big network."},
 "partner.sm.0": {"it": "Cos’è il Moon Festival", "en": "What Moon Festival is"},
