 "accessibilita-sito.l1.h": {"it": "Segnala un problema", "en": "Report a problem"},
 "accessibilita-sito.l1.p0": {"it": "Se qualcosa non funziona scrivici a <a href=\"mailto:info@associazionednart.it\">info@associazionednart.it</a>, rispondiamo entro [GIORNI].", "en": "If something doesn’t work, write to us at <a href=\"mailto:info@associazionednart.it\">info@associazionednart.it</a>, we reply within [DAYS]."},
 "accessibilita-sito.l2.h": {"it": "Accessibilità del festival", "en": "Festival accessibility"},
 "accessibilita-sito.l2.p0": {"it": "Per percorsi, navette, servizi e supporto durante il festival c’è una pagina dedicata.", "en": "For routes, shuttles, services and support during the festival there is a dedicated page."},
 "accessibilita-sito.lead": {"it": "A che punto è il sito con l’accessibilità e come segnalarci un problema.", "en": "Where the site stands on accessibility and how to report a problem."},
