 "area.call-installazioni": {"it": "Installazioni", "en": "Installations"},
 "call-installazioni.h1": {"it": "Call installazioni 2027", "en": "Open call for installations 2027"},
 "call-installazioni.lead": {"it": "Opere da abitare per tre sere: luce, suono, materia, sagome che trasformano vicoli, cortili e piazze del borgo.", "en": "Works to be lived in for three evenings: light, sound, matter and shapes that transform the lanes, courtyards and squares of the village."},
 "titolo.call-installazioni": {"it": "Call installazioni 2027 · Moon Festival", "en": "Open call for installations 2027 · Moon Festival"},
 "area.call-laboratori": {"it": "Laboratori", "en": "Workshops"},
 "call-laboratori.h1": {"it": "Proponi un laboratorio 2027", "en": "Propose a workshop 2027"},
 "call-laboratori.lead": {"it": "Hai un laboratorio da condividere? Raccontaci cosa vorresti costruire con il pubblico del festival.", "en": "Do you have a workshop to share? Tell us what you would like to build with the festival audience."},
 "titolo.call-laboratori": {"it": "Proponi un laboratorio 2027 · Moon Festival", "en": "Propose a workshop 2027 · Moon Festival"},
 "area.call-moon-lab": {"it": "Moon Lab", "en": "Moon Lab"},
 "call-moon-lab.h1": {"it": "Moon Lab 2027", "en": "Moon Lab 2027"},
 "call-moon-lab.lead": {"it": "Dodici giorni di residenza gratuita per costruire il festival: formazione, lavoro condiviso e vita in tenda. Pensato per chi ha tra i 18 e i 35 anni.", "en": "Twelve days of free residency to build the festival: training, shared work and life under canvas. Designed for people aged 18 to 35."},
 "titolo.call-moon-lab": {"it": "Moon Lab 2027 · Moon Festival", "en": "Moon Lab 2027 · Moon Festival"},
 "area.call-volontari": {"it": "Volontar* del festival", "en": "Festival volunteers"},
 "call-volontari.h1": {"it": "Volontar* del festival 2027", "en": "Festival volunteers 2027"},
 "call-volontari.lead": {"it": "Tre giorni dentro il festival: accoglienza, bar, piazza, backstage, media. Non servono competenze, servono ascolto e voglia di esserci.", "en": "Three days inside the festival: welcome, bar, squares, backstage, media. No skills needed, just listening and wanting to be there."},
 "titolo.call-volontari": {"it": "Volontar* del festival 2027 · Moon Festival", "en": "Festival volunteers 2027 · Moon Festival"},
 "area.call-cantina": {"it": "Apri la tua cantina", "en": "Open your cellar"},
