 "area.sostieni": {"it": "Sostieni", "en": "Support us"},
 "sostieni.h1": {"it": "Sostieni il Moon.", "en": "Support Moon."},
 "sostieni.lead": {"it": "Senza dover vendere un rene intergalattico. L’ingresso è libero: lo rendiamo possibile insieme.", "en": "No need to sell an intergalactic kidney. Entry is free: we make that possible together."},
 "sostieni.sm.0": {"it": "Perché sostenerlo", "en": "Why support it"},
